package com.trampolim.api.education;
import java.util.*;import java.security.SecureRandom;
import com.trampolim.api.radar.RadarBridge;import com.trampolim.api.career.CareerPassportLinkController;import static com.trampolim.api.radar.RadarModel.*;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Service @ConditionalOnProperty(name="trampolim.datasource.capacita.enabled",havingValue="true")
public class ProfessionalPassportService {
 private final org.springframework.transaction.support.TransactionTemplate tx;private final JdbcTemplate db;private final LearningAccess access;private final RadarBridge bridge;
 public ProfessionalPassportService(@Qualifier("capacitaJdbcTemplate")JdbcTemplate db,LearningAccess access,RadarBridge bridge,@Qualifier("capacitaTransactionManager")org.springframework.transaction.PlatformTransactionManager manager){this.tx=new org.springframework.transaction.support.TransactionTemplate(manager);this.db=db;this.access=access;this.bridge=bridge;}
 public record Import(String token,boolean consent){}public record Share(UUID credentialId,String recipientEmail,int days,boolean consent){}public record Verify(String token,String recipientEmail){}
 public Map<String,Object> claim(String email,Import p){long uid=access.account(email).id();if(p==null||!p.consent()||p.token()==null||!p.token().matches("[A-Za-z0-9_-]{43}"))bad("Informe o código gerado em Oportunidades e confirme a importação do resultado.");UUID reserved=tx.execute(transaction->{db.queryForObject("SELECT id FROM student_users WHERE id=? FOR UPDATE",Long.class,uid);var old=db.queryForList("SELECT * FROM learning_professional_credentials WHERE token_hash=?",RadarBridge.hash(p.token()));UUID id;if(old.isEmpty()){if(db.queryForObject("SELECT count(*) FROM learning_professional_credentials WHERE student_id=?",Integer.class,uid)>=100)bad("Limite de cem registros profissionais atingido.");id=UUID.randomUUID();db.update("INSERT INTO learning_professional_credentials(id,student_id,token_hash) VALUES (?,?,?)",id,uid,RadarBridge.hash(p.token()));}else{var r=old.getFirst();if(((Number)r.get("student_id")).longValue()!=uid)throw new ResponseStatusException(HttpStatus.NOT_FOUND);if(r.get("revoked_at")!=null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Vínculo revogado.");id=(UUID)r.get("id");}return id;});UUID id=reserved;var evidence=bridge.post("/integrations/career/challenges/passport/redeem",new CareerPassportLinkController.Redeem(p.token(),id));if(!evidence.path("status").asText().equals("ACTIVE"))throw new ResponseStatusException(HttpStatus.CONFLICT);if(db.update("UPDATE learning_professional_credentials SET state='ACTIVE',evidence=?::jsonb WHERE id=? AND revoked_at IS NULL",bridge.encode(evidence),id)==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Vínculo revogado durante a importação.");audit(uid,id,"PROFESSIONAL_RESULT_IMPORTED");return detail(email,id);}
 public Map<String,Object> detail(String email,UUID id){long uid=access.account(email).id();var rows=db.queryForList("SELECT * FROM learning_professional_credentials WHERE id=? AND student_id=?",id,uid);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return checked(rows.getFirst());}
 private Map<String,Object> checked(Map<String,Object> row){var result=new LinkedHashMap<String,Object>();result.put("id",row.get("id"));result.put("formalCertificate",false);result.put("recordType","COMPANY_ASSESSED_PROFESSIONAL_EVIDENCE");result.put("consentAt",row.get("consent_at"));if(row.get("revoked_at")!=null){result.put("status","REVOKED");return result;}try{var source=bridge.post("/integrations/career/challenges/passport/check",new CareerPassportLinkController.Check((UUID)row.get("id")));result.putAll(bridge.convert(source,Map.class));}catch(ResponseStatusException e){result.put("status",e.getStatusCode().is4xxClientError()?"INVALID":"UNAVAILABLE");}return result;}
 public Map<String,Object> list(String email,int offset,int limit){long uid=access.account(email).id();if(offset<0||offset>10000||limit<1||limit>20)bad("Use até vinte registros por página.");var rows=db.queryForList("SELECT * FROM learning_professional_credentials WHERE student_id=? ORDER BY consent_at DESC,id LIMIT ? OFFSET ?",uid,limit+1,offset);return Map.of("items",rows.stream().limit(limit).map(this::checked).toList(),"hasMore",rows.size()>limit);}
 public void revoke(String email,UUID id){long uid=access.account(email).id();if(db.update("UPDATE learning_professional_credentials SET state='REVOKED',revoked_at=COALESCE(revoked_at,CURRENT_TIMESTAMP) WHERE id=? AND student_id=?",id,uid)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);audit(uid,id,"PROFESSIONAL_RESULT_REVOKED");}
 @Transactional("capacitaTransactionManager")public Map<String,Object> share(String email,Share p){long uid=access.account(email).id();if(p==null||!p.consent()||p.credentialId()==null||p.days()<1||p.days()>30||!text(p.recipientEmail(),180).matches("[A-Za-z0-9.!#$%&'*+/=?^_{}|~-]+@[A-Za-z0-9-]+([.][A-Za-z0-9-]+)+"))bad("Confirme destinatário, credencial e prazo de 1 a 30 dias.");db.queryForObject("SELECT id FROM student_users WHERE id=? FOR UPDATE",Long.class,uid);if(!detail(email,p.credentialId()).get("status").equals("ACTIVE"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Compartilhe somente resultado válido.");if(db.queryForObject("SELECT count(*) FROM learning_professional_shares s JOIN learning_professional_credentials c ON c.id=s.credential_id WHERE c.student_id=? AND s.revoked_at IS NULL AND s.expires_at>CURRENT_TIMESTAMP",Integer.class,uid)>=100)bad("Revogue compartilhamentos antigos antes de criar outros.");byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);UUID id=UUID.randomUUID();db.update("INSERT INTO learning_professional_shares(id,credential_id,token_hash,recipient_email,expires_at) VALUES (?,?,?,?,CURRENT_TIMESTAMP+make_interval(days=>?))",id,p.credentialId(),RadarBridge.hash(token),p.recipientEmail().trim().toLowerCase(Locale.ROOT),p.days());audit(uid,id,"PROFESSIONAL_RESULT_SHARED");return Map.of("id",id,"token",token,"days",p.days());}
 public List<Map<String,Object>> shares(String email){return db.queryForList("SELECT s.id,s.credential_id,s.recipient_email,s.expires_at,s.revoked_at FROM learning_professional_shares s JOIN learning_professional_credentials c ON c.id=s.credential_id WHERE c.student_id=? ORDER BY s.consent_at DESC LIMIT 100",access.account(email).id());}
 public void revokeShare(String email,UUID id){long uid=access.account(email).id();if(db.update("UPDATE learning_professional_shares SET revoked_at=COALESCE(revoked_at,CURRENT_TIMESTAMP) WHERE id=? AND credential_id IN (SELECT id FROM learning_professional_credentials WHERE student_id=?)",id,uid)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);audit(uid,id,"PROFESSIONAL_SHARE_REVOKED");}
 public Map<String,Object> verify(String key,Verify p){bridge.authorize(key);if(p==null||p.token()==null||!p.token().matches("[A-Za-z0-9_-]{43}")||p.recipientEmail()==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);var rows=db.queryForList("SELECT c.* FROM learning_professional_shares s JOIN learning_professional_credentials c ON c.id=s.credential_id JOIN student_users u ON u.id=c.student_id AND u.account_status='ACTIVE' AND u.email_verified=TRUE WHERE s.token_hash=? AND LOWER(s.recipient_email)=LOWER(?) AND s.revoked_at IS NULL AND s.expires_at>CURRENT_TIMESTAMP",RadarBridge.hash(p.token()),p.recipientEmail());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return checked(rows.getFirst());}
 private void audit(long uid,UUID id,String event){db.update("INSERT INTO learning_assessment_audit(actor_id,resource_id,event) VALUES (?,?,?)",uid,id,event);}
}
